import{c as e,Q as o,j as n,m as s}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"ANTHROPIC ENGINEERS REVEALED HOW THEY BUILD AGENTS THAT RUN FOR DAYS","description":"","frontmatter":{"url":"https://x.com/_vmlops/status/2070533632859713937","title":"ANTHROPIC ENGINEERS REVEALED HOW THEY BUILD AGENTS THAT RUN FOR DAYS","author":"Vaishnavi","archived":"2026-06-27T00:00:00.000Z","duration":"01:10:22","handle":"@_vmlops","published":"2026-06-26T00:00:00.000Z","subtitle_lang":"English","type":"video"},"headers":[],"relativePath":"research/tweets/2026-06-26-vmlops-2070533632859713937.md","filePath":"research/tweets/2026-06-26-vmlops-2070533632859713937.md","lastUpdated":1785909234000}'),r={name:"research/tweets/2026-06-26-vmlops-2070533632859713937.md"};function a(i,t,l,g,h,p){return o(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="anthropic-engineers-revealed-how-they-build-agents-that-run-for-days-—-vmlops" tabindex="-1">ANTHROPIC ENGINEERS REVEALED HOW THEY BUILD AGENTS THAT RUN FOR DAYS — @_vmlops <a class="header-anchor" href="#anthropic-engineers-revealed-how-they-build-agents-that-run-for-days-—-vmlops" aria-label="Permalink to &quot;ANTHROPIC ENGINEERS REVEALED HOW THEY BUILD AGENTS THAT RUN FOR DAYS — @_vmlops&quot;">​</a></h1><p><strong>來源</strong>: <a href="https://x.com/_vmlops/status/2070533632859713937" target="_blank" rel="noreferrer">https://x.com/_vmlops/status/2070533632859713937</a><strong>作者</strong>: Vaishnavi (@_vmlops) <strong>發布日期</strong>: 2026-06-26 <strong>收錄日期</strong>: 2026-06-27 <strong>時長</strong>: 01:10:22 <strong>語言</strong>: 英語</p><hr><h2 id="核心摘要" tabindex="-1">核心摘要 <a class="header-anchor" href="#核心摘要" aria-label="Permalink to &quot;核心摘要&quot;">​</a></h2><blockquote><p>Anthropic 工程師 Andrew 和 Ash 在 engineer conference 上，回顧過去一年 Claude 從「20 分鐘 agent」演進到「能持續運行數天」的技術歷程，並深度拆解他們內部的 Generator-Evaluator harness 設計模式。</p></blockquote><ul><li><strong>三大瓶頸</strong>制約 long-running agent：Context 有限性（記憶清除、Context Rot、Context Sense Anxiety）、規劃能力不足（無法完整執行多步驟任務）、模型無法準確評估自身輸出品質</li><li><strong>Model + Harness 共演化</strong>：從 Sonnet 3.7（1 小時）到 Opus 4.6（12 小時），模型能力提升與 harness 設計同步推進；harness 不會消失，而是隨模型能力演化</li><li><strong>Generator-Evaluator-Planner 三角架構</strong>：Planner 產生高階 sprint 規劃；Generator 逐 sprint 建構；Evaluator 用獨立 context window 進行對抗性評估，並與 Generator 協商「完成條件契約（Done Contract）」</li><li><strong>自我評估是陷阱（Self-evaluation trap）</strong>：同一 context 內的模型無法客觀評估自己的輸出；必須使用<strong>對抗性獨立評估器</strong>（adversarial evaluator），類比人類的「評論家比創作者更容易批評作品」</li><li>五個關鍵 takeaway：避免自我評估、compaction 不等於連貫性（structured handoff 更優）、品味（subjective quality）是可量化的（設計四維評分：design/originality/craft/functionality）、透過讀 traces 理解模型行為、前端設計技能可以用 rubric 系統化訓練</li></ul><hr><h2 id="整理版-可讀逐字稿" tabindex="-1">整理版（可讀逐字稿） <a class="header-anchor" href="#整理版-可讀逐字稿" aria-label="Permalink to &quot;整理版（可讀逐字稿）&quot;">​</a></h2><h3 id="開場-agent-長時運行的三大挑戰-00-00–02-43" tabindex="-1">開場：Agent 長時運行的三大挑戰（00:00–02:43） <a class="header-anchor" href="#開場-agent-長時運行的三大挑戰-00-00–02-43" aria-label="Permalink to &quot;開場：Agent 長時運行的三大挑戰（00:00–02:43）&quot;">​</a></h3><p>Andrew（Anthropic applied AI team，London）回顧 Boris（Claude Code 創始人）在 Claude Code 一週年時的感言：一年前 Claude 還在為 bash 命令和字串轉義掙扎、只能跑 20 分鐘，現在幾乎所有 Claude Code 都是 Claude Code 自己寫的，且能持續運行數天。</p><p>為什麼 agent 難以長時運行？Andrew 歸納三大挑戰：</p><ol><li><strong>Context 限制</strong>：Context window 有限，新 session 等於失憶；隨 session 深入出現「Context Rot」（連貫性衰減）；接近 context 上限時模型出現「Context Sense Anxiety」（急著收尾）</li><li><strong>規劃能力不足</strong>：模型傾向一次性做完所有事，或做到一半停下；或是 context 耗盡後留下未完成的應用</li><li><strong>無法評估自身輸出</strong>：模型傾向說你想聽的話；看到半成品功能也可能認為「看起來完成了」，或建了 UI 但 backend 根本不存在</li></ol><h3 id="解決之道-model-與-harness-的協同演化-02-43–15-18" tabindex="-1">解決之道：Model 與 Harness 的協同演化（02:43–15:18） <a class="header-anchor" href="#解決之道-model-與-harness-的協同演化-02-43–15-18" aria-label="Permalink to &quot;解決之道：Model 與 Harness 的協同演化（02:43–15:18）&quot;">​</a></h3><p>兩個主要解法：</p><p><strong>（一）改善模型本身</strong>：「meter chart」顯示 agent 在最簡 scaffold 下完成 50% 任務所需時間，從 Opus 3.7 的約 1 小時，到 Opus 4.6 的 12 小時（代表整個工作日）。</p><p><strong>（二）改善 Harness（腳手架）</strong>：Anthropic Agent SDK 提供核心原語：agent loop（決定用哪些工具）、MCP server、sub-agent 委派、Claude.md / skills / slash commands 載入、權限系統。</p><p>重要里程碑回顧：</p><ul><li><strong>Sonnet 3.5</strong>：第一個展現實際 coding 能力的模型，能看自己的輸出並迭代（pre-Claude Code 時代的 aha moment）</li><li><strong>Computer Use</strong>：能截圖、點擊、測試自己的程式碼</li><li><strong>Claude Code（Feb 2025）</strong>：以 Sonnet 3.7 發布，最初定位是「實驗性工具，用來了解開發者如何使用 Claude 進而改善基礎模型」</li><li><strong>Ralph Loop（Jeffrey Huntley 技術）</strong>：「deterministically bad is better than unpredictably good」——可預測地失敗優於不可預測的成功。Claude Code 內建了 Claude 版本的 Ralph Loop plugin（單 session 內靠 compaction 維持，並非嚴格的 fresh context window 版本）</li><li><strong>Claude Code 2.0</strong>：加入 Checkpoints，模型更能追蹤自身 token 消耗、管理 context</li><li><strong>Haiku 4.5 + Opus 4.5</strong>：sub-agent 經濟性大幅提升，能跑約 30 小時</li><li><strong>Sonnet 4.6 + Opus 4.6</strong>：Opus 4.6 被定位為最「agentic」的模型，能決定使用哪些工具、運行更長時間；Agent Teams（sub-agent 間直接溝通）、Server-side Compaction（可無限運行）、1M context GA</li></ul><h3 id="ash-接棒-generator-evaluator-架構的技術細節-15-18–36-38" tabindex="-1">Ash 接棒：Generator-Evaluator 架構的技術細節（15:18–36:38） <a class="header-anchor" href="#ash-接棒-generator-evaluator-架構的技術細節-15-18–36-38" aria-label="Permalink to &quot;Ash 接棒：Generator-Evaluator 架構的技術細節（15:18–36:38）&quot;">​</a></h3><p><strong>核心洞察：自我評估是陷阱。</strong></p><p>模型在自己建構的 context 內無法客觀評估自己的輸出。解法類比人類直覺：批評一頓飯比自己烹飪容易多了——因此要<strong>獨立訓練一個嚴格的 critic（evaluator）</strong>，而非要求 builder 自我批評。</p><p><strong>設計品味的量化</strong>：前端 UI 常被認為是主觀的，但只要有強烈觀點就能量化：四維評分（Design / Originality / Craft / Functionality），並有意識地根據模型特性調整權重（例如 Opus 4.6 功能性已很強，所以更強調 Design 和 Originality）。評估器可以用參考網站校準品味，防止 AI slop（紫色漸層、一般性 AI 美學）。</p><p><strong>GAN 式 Harness 的優勢</strong>：Generator 卡在某個維度（如 originality 持續低分）時，adversarial harness 會直接丟棄重來——這是 single-agent loop 或 Ralph Loop 做不到的。</p><p><strong>加入 Planner 後的完整架構</strong>：</p><ol><li><strong>Planner</strong>：將一行提示詞展開為高階 sprint 清單（刻意不細化技術細節，避免早期規劃錯誤沿 sprint 級聯放大）</li><li><strong>Generator + Evaluator 協商 Done Contract</strong>：在 Generator 開始寫任何程式碼前，Generator 提出「我要做 X，你測試 Y」，Evaluator 可能回推「scope 太大、測試太弱、漏掉邊界條件」，兩方協商直到達成明確的完成條件</li><li><strong>Generator 建構</strong>：Evaluator 對照 Done Contract 評分，而非對照原始 spec</li><li><strong>Evaluator 實際使用 app 測試</strong>（Playwright MCP）：找到只有真正使用才能發現的 bug</li></ol><p><strong>Opus 4.6 帶來的架構簡化</strong>：原本複雜的 per-sprint evaluator 設計在 Opus 4.6 下可以大幅簡化——模型能在 2 小時連續 build 中保持連貫性，不再需要強制 per-sprint 評估。一個連續 session 就足以處理非常長的建構任務。</p><h3 id="q-a-精華-36-38–01-10-07" tabindex="-1">Q&amp;A 精華（36:38–01:10:07） <a class="header-anchor" href="#q-a-精華-36-38–01-10-07" aria-label="Permalink to &quot;Q&amp;A 精華（36:38–01:10:07）&quot;">​</a></h3><p><strong>評估器是 per-project 還是可重用？</strong> 目標是可重用：找出模型的共通弱點（如前端設計品質），而非針對特定 app 定制。</p><p><strong>Context Rot 和 smart zone 問題</strong>：Ralph Loop 的核心思想是讓模型保持在 context 的「smart zone」（前 40%）。但 Ash 認為這是暫時問題——Opus 4.6 已能在更長的 context 內保持連貫。Server-side compaction 讓這個問題更接近解決。</p><p><strong>Human in the loop</strong>：目前的探索方向是「能做到完全自主的程度嗎？」若需要插入人工，Hooks 是最自然的原語（特定 stop condition 觸發 evaluator 把控制權交回人類）。但也可以採取「跑 10 個平行版本，人工挑選成功的 3 個」模式。</p><p><strong>讀 traces 的重要性</strong>：真正理解模型行為需要逐行讀 traces——「把自己放進模型的位置」，像閉著眼睛瀏覽網頁一樣。這是 Ash 在 Anthropic 內部開發 Chrome agent 時的核心實踐。</p><p><strong>Brownfield vs Greenfield</strong>：目前這個 harness 模式最適合 greenfield 新應用；brownfield（既有代碼庫）需要更多控制和定制化的 rubric。</p><hr><h2 id="逐字稿-含時間戳" tabindex="-1">逐字稿（含時間戳） <a class="header-anchor" href="#逐字稿-含時間戳" aria-label="Permalink to &quot;逐字稿（含時間戳）&quot;">​</a></h2><p><strong>[00:00 → 00:05]</strong> Thanks everyone for joining our first session of the engineer conference, so glad you&#39;re spending it with us</p><p><strong>[00:05 → 00:13]</strong> My name is Andrew. I&#39;m on the applied AI team based out of London working as a solution architect with a lot of our digital native and industry&#39;s customers</p><p><strong>[00:13 → 00:18]</strong> So yeah, I&#39;m gonna give a little bit of a history tour trip down memory lane</p><p><strong>[00:18 → 00:23]</strong> But really with the focus on all the things that we&#39;ve shipped that lead to agents being able to run</p><p><strong>[00:23 → 00:27]</strong> For multiple hours or even days at a time and then I&#39;ll hand over to Ash to do the</p><p><strong>[00:27 → 00:29]</strong> State-of-the-art</p><p><strong>[00:29 → 00:31]</strong> right, okay, so</p><p><strong>[00:31 → 00:35]</strong> Little quote from or from Twitter from Boris the creator of Claude code</p><p><strong>[00:35 → 00:37]</strong> This was on the one year anniversary of Claude code</p><p><strong>[00:38 → 00:43]</strong> Basically saying a year ago Claude was struggling just to write bash commands and escapeings strings</p><p><strong>[00:43 → 00:50]</strong> You know, we&#39;re now at the point where almost all Claude code is being written by Claude code</p><p><strong>[00:50 → 00:53]</strong> And-it-can-run effectively for days at a time</p><p><strong>[00:53 → 01:00]</strong> So sort of a big big swing over just the course of a year and I&#39;ll walk through that history a little bit now</p><p><strong>[01:00 → 01:03]</strong> But just to I&#39;ll zoom in here</p><p><strong>[01:04 → 01:08]</strong> Just to sort of frame the problem up like why why is it that it&#39;s really</p><p><strong>[01:08 → 01:14]</strong> Difficult for these agents to run for extended periods of time. I think broadly there&#39;s three big buckets</p><p><strong>[01:14 → 01:20]</strong> Some are more intuitive than others. So firstly context. I think we all understand context windows very much finite</p><p><strong>[01:20 → 01:25]</strong> So you start a new session. There&#39;s like amnesia. The agent has to start from scratch. So you need some sort of memory components</p><p><strong>[01:26 → 01:30]</strong> Also as you&#39;re working through a context window, there&#39;s this notion of context rot</p><p><strong>[01:30 → 01:33]</strong> So there&#39;s less coherence as you&#39;re getting deeper into that session</p><p><strong>[01:34 → 01:40]</strong> Also, you might get to the point where the model actually exhibits what&#39;s called context sense anxiety</p><p><strong>[01:40 → 01:45]</strong> So it gets kind of nervous as it reaches the end of its context window and it just quickly hurries up to finish</p><p><strong>[01:45 → 01:48]</strong> What it&#39;s doing this kind of leads into planning so</p><p><strong>[01:49 → 01:52]</strong> In general models are not that great at planning just out of the box</p><p><strong>[01:53 → 01:56]</strong> They might try and do everything in just one shot or for example</p><p><strong>[01:56 → 02:03]</strong> They might build half a feature and then stop or they might just run out of context altogether and sort of leave a half finished app built</p><p><strong>[02:04 → 02:06]</strong> But then maybe less intuitively</p><p><strong>[02:06 → 02:09]</strong> Models are really bad at judging their own output</p><p><strong>[02:09 → 02:13]</strong> So I know we all know that miles can be sick authentic and sort of tell you what you want to hear</p><p><strong>[02:13 → 02:18]</strong> but this applies as well to coding tasks so it might look at a feature and see that it&#39;s</p><p><strong>[02:18 → 02:21]</strong> Sort of half half baked or a little bit implemented and say yeah, okay</p><p><strong>[02:21 → 02:26]</strong> That looks done and then we&#39;ll move on to the next thing or it might build a feature like a button</p><p><strong>[02:26 → 02:28]</strong> But actually the back end, you know, it doesn&#39;t exist for it</p><p><strong>[02:28 → 02:43]</strong> There&#39;s sort of no nothing behind that but it looks like the</p><p><strong>[02:43 → 02:48]</strong> So there&#39;s there&#39;s two ways really we can we can fix these things the first one is obviously the model so</p><p><strong>[02:49 → 02:54]</strong> Baking it all into the model weights themselves and I&#39;m sure you&#39;ve all seen this this meter charts</p><p><strong>[02:54 → 02:57]</strong> Basically, how long can an agent run for with a-minimal scaffold?</p><p><strong>[02:58 → 03:02]</strong> where it&#39;s completing 50% of the tasks and you&#39;ll see from</p><p><strong>[03:03 → 03:07]</strong> 7 it&#39;s around one hour and up to opus 4.6 one year later</p><p><strong>[03:07 → 03:12]</strong> It&#39;s at 12 hours so an entire day and we&#39;ve of course, you know managed to get that running much longer</p><p><strong>[03:12 → 03:16]</strong> Other people have as well, but this is just a sort of very minimal scaffold</p><p><strong>[03:16 → 03:21]</strong> The second thing that you can do is of course make changes to the harness itself</p><p><strong>[03:21 → 03:24]</strong> so this is the scaffolding around the model and</p><p><strong>[03:25 → 03:30]</strong> We have the agent SDK which ships with all the primitives that we&#39;ve been building over time</p><p><strong>[03:30 → 03:37]</strong> So there&#39;s the core agent loop itself where you have Claude model that&#39;s determining what to do what tools to run</p><p><strong>[03:37 → 03:42]</strong> Maybe it&#39;s pulling in some tools from MCP server. It might delegate some tasks to a sub agent</p><p><strong>[03:42 → 03:47]</strong> It&#39;s bringing in all the context from things like Claude and D or the skills that are loaded or slash commands</p><p><strong>[03:47 → 03:53]</strong> There&#39;s a whole permission system and this this will change over time as well as the models get better and improve</p><p><strong>[03:53 → 03:57]</strong> But these are sort of the the core permit with and then of of course you just</p><p><strong>[03:57 → 04:05]</strong> Have to build your own harness for what are there to do to the things that ash later on when we get into more long-running agents</p><p><strong>[04:05 → 04:13]</strong> I think what&#39;s also interesting is just looking back at the last year of releases is that when we&#39;ve released a model</p><p><strong>[04:17 → 04:26]</strong> Really these things are co-co evolving together. So we&#39;ll just look</p><p><strong>[04:26 → 04:31]</strong> I suppose firstly just prehistory beyond you know one year ago. I think we all remember that that period where Claude had the artifact section of Claude.ai and</p><p><strong>[04:32 → 04:38]</strong> Sonnet 3.5 was the first model that really showed promise when it came to coding and it can now verify that it could look at</p><p><strong>[04:38 → 04:40]</strong> What I built and sort of iterate from there</p><p><strong>[04:40 → 04:43]</strong> And that was quite an aha moment sort of pre-clawed code</p><p><strong>[04:43 → 04:45]</strong> , but then also we</p><p><strong>[04:45 → 04:48]</strong> Shaped computer use so it could start clicking around taking screenshots</p><p><strong>[04:49 → 05:06]</strong> Testing</p><p><strong>[05:07 → 05:14]</strong> Preview and I think an interesting quote that I pulled from this release actually is that the goal of Claude code was to better understand how</p><p><strong>[05:14 → 05:18]</strong> Developers use Claude for coding to inform future model improvements</p><p><strong>[05:18 → 05:26]</strong> So to release Claude code the whole idea was for it to be somewhat experimental to inform how we actually improve the base model itself</p><p><strong>[05:26 → 05:29]</strong> And you&#39;ll see this trend that over time the models become better</p><p><strong>[05:30 → 05:34]</strong> The harness certain a specs of it might become less necessary or it will evolve</p><p>[... 共 735 segments，完整逐字稿見 /tmp/claude-scratch/out/vmlops.txt ...]</p>',99)])])}const c=e(r,[["render",a]]);export{u as __pageData,c as default};
